import hashlib,json,os,pathlib,shlex,subprocess,tempfile
image=pathlib.Path('/private/tmp/awai156-sigguard.r8ZGISjT/guard.elf').read_bytes();digest='5dfca800f1178e33b41b75ec4a9d18e17561e1e75c4fc7c97fb8ce3f45390264';assert hashlib.sha256(image).hexdigest()==digest
s=json.loads(subprocess.check_output(['tailscale','status','--json']));peer=next(x for x in s['Peer'].values() if x.get('HostName')=='xavier');assert peer.get('Online') and peer.get('sshHostKeys')
code='''import hashlib,json,os,pathlib,resource,subprocess,sys,tempfile\nb=sys.stdin.buffer.read(4097);assert len(b)==4096 and hashlib.sha256(b).hexdigest()==%s\nwith tempfile.TemporaryDirectory(prefix="awai156-guard-") as d:\n p=pathlib.Path(d)/"guard";p.write_bytes(b);p.chmod(0o700)\n def limits():\n  resource.setrlimit(resource.RLIMIT_CPU,(5,5));resource.setrlimit(resource.RLIMIT_CORE,(0,0))\n try:\n  r=subprocess.run([str(p),"--version"],cwd=d,preexec_fn=limits,capture_output=True,text=True,timeout=8);print(json.dumps({"exit":r.returncode,"version_is_curl":r.stdout.startswith("curl "),"stderr_nonempty":bool(r.stderr)}))\n except subprocess.TimeoutExpired:print(json.dumps({"timeout":True}))\nprint(json.dumps({"task_dir_removed":not pathlib.Path(d).exists()}))'''%repr(digest)
with tempfile.TemporaryDirectory(prefix='awai156-hostkeys-') as d:
 k=pathlib.Path(d)/'known';k.write_text(''.join('xavier '+x+'\n' for x in peer['sshHostKeys']));os.chmod(k,0o600)
 c=['ssh','-o','BatchMode=yes','-o','ConnectTimeout=6','-o','StrictHostKeyChecking=yes','-o','HostKeyAlias=xavier','-o','UserKnownHostsFile='+str(k),'-o','GlobalKnownHostsFile=/dev/null','-o','HostName='+peer['TailscaleIPs'][0],'xavier@xavier','/usr/bin/python3 -c '+shlex.quote(code)]
 r=subprocess.run(c,input=image,capture_output=True,timeout=15);print('ssh_exit',r.returncode);print(r.stdout.decode());print('stderr_nonempty',bool(r.stderr))
